(0x01a0ba3758137ea0bced6817c8a2b222, '2026-09-19 15:09:44.339927', '2026-10-05 01:37:57.511182', '2026-09-19 00:00:00.000000', 'e-commerce platforms and CMS ecosystems (Shopify, Magento, SFCC, etc.).', NULL, 0x01a0b007e9be78f5975b8a985e2750ce, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0ba37d0807acd98867511aa280f36, '2026-09-19 15:10:15.168680', '2026-10-05 01:37:57.499729', '2026-09-19 00:00:00.000000', 'Країни ЄС\nКраїни, де розглядаємо кандидатів\nВ профілі: Україна', NULL, 0x01a0b007e9bc733dbd03655071371f7f, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0ba8a3fed78e2ad6c44cdc7dc426b, '2026-09-19 16:40:17.645559', '2026-10-05 01:37:57.484304', '2026-09-19 00:00:00.000000', 'Доброго дня, Віталію. \nДякуємо за відгук щодо вакансії.\n Будь ласка, надішліть посилання, \nза якими можна ознайомитися з результатами\n вашої професійної діяльності (SaaS-рішення, e-commerce тощо). \nДякую.\n\nЗ повагою,\nSilkway Solutions.', NULL, 0x01a0b007e9c079db8a3a38073a2271ef, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0ba8f841873abb2172f9a4ae804d6, '2026-09-19 16:46:02.776223', '2026-10-05 01:37:57.467088', '2026-09-19 00:00:00.000000', 'Доброго дня!\nДякую за повідомлення.\n\nНадсилаю посилання на мій LinkedIn-профіль, \nде можна ознайомитися з моїм професійним досвідом та проєктами:\n\nhttps://www.linkedin.com/in/vitalii-sotnikov/\n\nБуду радий надати додаткову інформацію \nщодо конкретних проєктів або результатів моєї роботи, \nякщо це буде потрібно.\n\nДякую!\nВіталій Сотников', NULL, 0x01a0b007e9c079db8a3a38073a2271ef, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c3ffd53976d0b08b325f21dfbb81, '2026-09-21 12:45:18.521415', '2026-10-05 01:37:57.449114', '2026-09-21 00:00:00.000000', 'Ваш відгук на цю позицію відхилено\nПричина відмови: Невідповідність навичок.', NULL, 0x01a0b007e9c079db8a3a38073a2271ef, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c401611272639be2fd9ff8e1cfe1, '2026-09-21 12:46:59.858114', '2026-10-05 01:37:57.433824', '2026-09-21 00:00:00.000000', 'Олександр\nДоброго дня Віталій, поки на холді позиція', NULL, 0x01a0b007e9c17ecbb02e2e49fee9c7b6, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c413329472369626c05e48f8d3dd, '2026-09-21 13:06:27.604095', '2026-10-05 01:37:57.414445', '2026-09-21 00:00:00.000000', 'привіт!😊\nМене звати Катерина, я рекрутерка Ringostat.\n\nРада заочному знайомству та буду вдячна за невелике уточнення :)\n\n1. Підкажіть, будь ласка, чи є у вас досвід використання \nAI-інструментів (Cursor, Claude Code) для прискорення розробки, \nрефакторингу та дебагінгу коду?\n\n2. Чи маєте досвід роботи з Redis?', NULL, 0x01a0b007e9c37cb591283f68dcb8a4d2, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c4145f067441ac21c8b103f043fb, '2026-09-21 13:07:44.518254', '2026-10-05 01:37:57.397691', '2026-09-21 00:00:00.000000', 'Доброго дня.\n\n> 1. Підкажіть, будь ласка, чи є у вас досвід використання\n> AI-інструментів (Cursor, Claude Code) для прискорення \n> розробки, рефакторингу та дебагінгу коду?\nТак, використовую AI-інструменти як допоміжні засоби в розробці. \nЗокрема, регулярно використовую ChatGPT та Claude Code для прискорення розробки. \nПри цьому сприймаю їх саме як інструменти-помічники, а фінальне рішення приймаю самостійно.\n\n> 2. Чи маєте досвід роботи з Redis?\nТак, маю досвід роботи з Redis. Використовував його як кеш-адаптер у \nSymfony для кешування даних та оптимізації роботи застосунку.', NULL, 0x01a0b007e9c37cb591283f68dcb8a4d2, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c415c5d37524a367507df7895c6c, '2026-09-21 13:09:16.371304', '2026-10-05 01:37:57.382351', '2026-09-21 00:00:00.000000', 'Вітаю! \nДякую за відгук! \nМи взяли Ваше резюме до розгляду. \nПізніше повернусь до Вас з відповіддю! Гарного дня!', NULL, 0x01a0b007e9a77c869eda085c6ba0ed1b, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c429a0d7734c87970f6b858c8fb4, '2026-09-21 13:30:57.623184', '2026-10-05 01:37:57.363701', '2026-09-21 00:00:00.000000', 'понедельник 9.46\nувидел только в 16.00\n\nВіталій добрий ранок, на 11ту було б зручно?', NULL, 0x01a07c0336707cd581be1d9bf71a1d5a, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c42e4aba7f068b9e1c4c41cde678, '2026-09-21 13:36:03.258943', '2026-10-05 01:37:57.349967', '2026-09-21 00:00:00.000000', 'Доброго дня!\n\nПерепрошую, не зміг вчасно відповісти щодо запропонованого часу.\n\nПропоную призначити інший зручний для вас час для зустрічі, \nпочинаючи із середи, 23 вересня. \nГотовий підлаштуватися під ваш графік.\n\nДля більш оперативної комунікації можемо \nпоспілкуватися в Telegram: https://t.me/vitaliisotnykov\n\nДякую за розуміння!', NULL, 0x01a07c0336707cd581be1d9bf71a1d5a, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c433f249705f94c78187f2404f5b, '2026-09-21 13:42:13.832975', '2026-10-05 01:37:57.323915', '2026-09-21 00:00:00.000000', 'Mandatory hands-on experience with Apache Kafka', NULL, 0x01a0c431c0167a4cb5ea7f426a59c682, 0x01a1084464e179dc91356f71aca2a75f);
INSERT INTO `notes` (`id`, `created_at`, `updated_at`, `noted_at`, `description`, `company_id`, `vacancy_id`, `user_id`) VALUES
(0x01a0c438013772c18e96421d48613b23, '2026-09-21 13:46:39.799134', '2026-10-05 01:37:57.315174', '2026-09-21 00:00:00.000000', '- Hands-on experience with AWS services: RDS, ECS, SQS, SNS, SES, Lambda\n- Deep understanding of Docker and containerisation\n- Knowledge of Infrastructure as Code using Terraform\n- Proven track record of building and maintaining high-load, scalable backend systems', NULL, 0x01a0c431c02774bbb128f2609e444cb7, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c439562e771bb07ffcb1040fbafd, '2026-09-21 13:48:07.086420', '2026-10-05 01:37:57.307120', '2026-09-21 00:00:00.000000', 'part-time', NULL, 0x01a0c431c02175a9a02b33847f6ba33e, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c4412e567395a6756088d0b5f7dd, '2026-09-21 13:56:41.174210', '2026-10-05 01:37:57.298034', '2026-09-21 00:00:00.000000', 'Віталію, дякую за відповіді на питання!\n\nЗапрошую вас поспілкуватися з моїм колегою Максимом (Recruiter) \nна співбесіді у Google Meet, у середу, 23 вересня о 16:45 за київським часом.\n\nОсь посилання, аби приєднатися до зустрічі: \nhttps://meet.google.com/vov-gvji-bws\n\nПідкажіть, будь ласка, чи буде вам зручно поспілкуватися у вказаний час? \nТакож хочу уточнити, чи не будете ви проти, якщо ми зробимо відеозапис співбесіди?\n\nЦей запис потрібен для роботи з ШІ-алгоритмом \nLITI https://mc.today/uk/netpeak-group-stvorila-vlasnij-shi-produkt-ta-vikoristovuye-jogo-v-rekrutingu-yak-vin-pratsyuye/?utm_source=chatgpt.com \n— нашою власною технологією, яка допомагає в оцінці кандидатів.\n\nАлгоритм аналізує транскрибований текст розмови — тобто перетворену \nу текстовий формат відеобесіду. Ми не здійснюємо аналіз відео, зображення,\nзовнішнього вигляду, поведінки чи голосу кандидата, лише аналіз отриманого тексту.\n\nЦе технологічне рішення від FRACTAL допомагає нашим наймаючим \nменеджерам у процесі найму і дає можливість більш різносторонньо оцінити кандидата.\n\nБудь ласка, повідомте, чи погоджуєтеся ви на відеозапис і подальшу \nобробку текстової інформації. Хочемо запевнити вас, \nщо всі дані залишаться конфіденційними \nта будуть використані виключно для цілей найму і не передаватимуться третім особам.\n\nНа зустрічі ми детальніше розкажемо про нашу вакансію та компанію, \nа також спробуємо дізнатися більше про вас :) \nУ середньому співбесіда триває близько 1 год.\n\nПодбайте і про відеозв’язок: аби ми один одного не тільки чули, а й бачили :)', NULL, 0x01a0b007e9c37cb591283f68dcb8a4d2, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c441d5037b24830f12e56f2e2666, '2026-09-21 13:57:23.843695', '2026-10-05 01:37:57.288817', '2026-09-21 00:00:00.000000', 'Доброго дня!\n\nДякую за запрошення та детальну інформацію.\n\nТак, мені буде зручно поспілкуватися \nу середу, 23 вересня, о 16:45 за київським часом.\n\nТакож погоджуюся на відеозапис співбесіди \nта подальшу обробку текстової інформації \nвідповідно до зазначених вами цілей.\n\nДо зустрічі!', NULL, 0x01a0b007e9c37cb591283f68dcb8a4d2, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c47a08dc7ee6b76297ed3082fffb, '2026-09-21 14:58:47.132942', '2026-10-05 01:37:57.280035', '2026-09-21 00:00:00.000000', 'Invite\n\nСсылка на встречу\nhttps://meet.google.com/vov-gvji-bws\n\nПрисоединиться по номеру телефона\n(GB) +44 20 3956 1058\nPIN: 923796692\n\nДополнительные номера телефонов\nhttps://tel.meet/vov-gvji-bws?pin=4108788773121&hs=0\n\nSotnykov Vitalii: https://t.netpeak.group/task/9987434\nВакансія: https://career.fractal.partners/ua/vacancy/ade92f/\n\nКогда\nсреда, 23 сент 2026 ⋅ 16:45 – 17:30 (Восточная Европа - Киев)\n\nГости\nKateryna Taran– организатор\nMaksym Martynovskyi\nvtsot7@gmail.com', NULL, 0x01a0b007e9c37cb591283f68dcb8a4d2, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c47a08dd70048fa46852ebae1f33, '2026-09-21 14:58:47.132998', '2026-10-05 01:37:57.271978', '2026-09-21 00:00:00.000000', 'відправила вам інвайт на пошту)\n\nТакож хочу додати трохи інформації про Ringostat, \nщоб у вас була можливість ознайомитись з нашим продуктом перед співбесідою:\n\nСайт Ringostat: https://ringostat.com/en/\nНаш блог: https://blog.ringostat.com/uk/\n\nДізнайтесь, чому платформа Ringostat краща\n за аналогічні сервіси: https://ringostat.com/uk/benefits/', NULL, 0x01a0b007e9c37cb591283f68dcb8a4d2, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c8aee58c741f91cde7db8e981a51, '2026-09-22 10:35:00.364253', '2026-10-05 01:37:57.261594', '2026-09-22 00:00:00.000000', 'Віталію, доброго дня!\n\nДякую за Ваш відгук на нашу вакансію та перепрошую за затримку з відповіддю.\n\nНа жаль, вакансію, на яку Ви відгукувалися, ми вже закрили. \nАле зараз у нас є інша відкрита позиція PHP Developer на схожий проєкт, \nі Ваш досвід може бути релевантним.\n\nПідкажіть, будь ласка, чи актуальний для Вас ще пошук роботи \nта чи було б цікаво розглянути іншу нашу вакансію?\n\nТакож підкажіть, будь ласка, які у Вас зараз зарплатні очікування?\n\nДякую!', NULL, 0x01a077e29a6d7b8d8e2049e9f54b451b, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c8b2cf3372f688c60ab148bec2d0, '2026-09-22 10:39:16.787180', '2026-10-05 01:37:57.253430', '2026-09-22 00:00:00.000000', 'Доброго дня!\n\nДякую за відповідь.\n\nТак, пошук роботи для мене наразі актуальний.\n\nБуду вдячний, якщо надішлете детальнішу інформацію про позицію та проєкт.\n\nЩодо зарплатних очікувань — орієнтуюся на рівень $2,500.\n\nДякую! Буду радий ознайомитися з деталями.', NULL, 0x01a077e29a6d7b8d8e2049e9f54b451b, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c8d06f2c7e5a9a7b60426d0efd10, '2026-09-22 11:11:38.284907', '2026-10-05 01:37:57.245815', '2026-09-22 00:00:00.000000', 'Доброго дня!\n\nЯкщо пропозиція щодо зустрічі ще актуальна, \nпропоную обрати зручний для вас час через мій календар:\n\nhttps://calendar.app.google/UgRGVbm3yby1khHDA\n\nБуду радий поспілкуватися!\n\nВіталій', NULL, 0x01a07c0336707cd581be1d9bf71a1d5a, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a0c8fa704e753c90d8721dd0712d71, '2026-09-22 11:57:31.086325', '2026-10-05 01:37:57.235792', '2026-09-22 00:00:00.000000', 'Віталій дякую!\nЗабронювала на 13ту годину в пятницю', NULL, 0x01a07c0336707cd581be1d9bf71a1d5a, 0x01a1084464e179dc91356f71aca2a75f),
