(0x01a10c847c487c8cb98575a90d793ecd, '2026-10-05 14:42:51.592794', '2026-10-05 14:43:36.367082', '2026-10-05 14:42:51.000000', 'заявка на DOU\nhttps://docs.google.com/forms/u/1/d/e/1FAIpQLSfJsAVlBNLMJn0Oq52N1EIIcxIvBQO5hcOmL9vg44f9SLnxaw/formResponse?pli=1', NULL, 0x01a0f7b780fb7f5b960feccaf19bf311, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a10c854dde7b628949d5eeda36e00f, '2026-10-05 14:43:45.246719', '2026-10-05 14:44:29.603901', '2026-10-05 14:43:45.000000', 'вопросы типа\n\nОтношение к AI-инструментам (The AI Check):\nЭта роль требует интеграции backend API с frontend-компонентами, сгенерированными ИИ (Lovable / React). Комфортен ли вам такой рабочий процесс, или вы предпочитаете писать UI исключительно с нуля вручную? \n\nОпыт с Laravel (The Laravel Check):\nКратко опишите самую сложную биллинговую систему, интеграцию со Stripe или архитектуру cron-задач, которую вы создали с использованием PHP/Laravel. \n\nЧасовой пояс (The Timezone Check):\nКомфортно ли вам пересекаться минимум на 4 часа в день с рабочим временем по Нью-Йорку (US Eastern Time)?', NULL, 0x01a0f7b780fb7f5b960feccaf19bf311, 0x01a1084464e179dc91356f71aca2a75f),
(0x01a10c8736b670ad8a35a2758b1a38ae, '2026-10-05 14:45:50.390034', '2026-10-05 14:46:14.945707', '2026-10-05 14:45:50.000000', 'Done\n\nждать не вижу смысла', NULL, 0x01a0f7b780fb7f5b960feccaf19bf311, 0x01a1084464e179dc91356f71aca2a75f),
